-- Additional Tesla Кыргызстан community FAQ (2026-11-21).
-- Safe to re-run; existing FAQ rows and other tables remain unchanged.
-- Run after database/010_faq.sql.
INSERT INTO ev_faq (category, question, answer, sort_order, is_published)
SELECT 'charging', 'Почему Tesla начинает зарядку только со второй или третьей попытки?', 'Причинами могут быть задержка авторизации станции, плохой контакт, ошибка обмена данными или несовместимый адаптер. Запишите ошибку и номер порта, сообщите оператору. При нагреве, запахе гари или видимых повреждениях прекратите попытки.', 110, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему Tesla начинает зарядку только со второй или третьей попытки?')
UNION ALL
SELECT 'charging', 'Почему зарядка внезапно отключается до установленного лимита?', 'Проверьте сообщения автомобиля, статус оплаты, температуру разъёма, ограничения станции и состояние кабеля. Повторяющиеся отключения на разных станциях — повод проверить зарядный порт и систему зарядки в сервисе.', 120, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему зарядка внезапно отключается до установленного лимита?')
UNION ALL
SELECT 'charging', 'Почему одна станция заряжает быстрее другой при одинаковой заявленной мощности?', 'Фактическая мощность зависит от температуры и процента заряда батареи, распределения мощности между портами, ограничений станции и автомобиля. Сравнивайте условия при одинаковом уровне заряда.', 130, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему одна станция заряжает быстрее другой при одинаковой заявленной мощности?')
UNION ALL
SELECT 'charging', 'Можно ли доверять надписи «свободна» на карте станции?', 'Статус может поступать с задержкой и не показывает все неисправности. Перед поездкой проверьте время обновления данных и наличие альтернативной станции. Свободный разъём не всегда означает, что он исправен.', 140, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли доверять надписи «свободна» на карте станции?')
UNION ALL
SELECT 'charging', 'Почему Tesla не начинает DC-зарядку после подключения переходника?', 'Один физически подходящий разъём не обеспечивает совместимость протоколов. Убедитесь в поддержке DC-зарядки автомобилем, правильном типе и исправности адаптера и соответствии станции. При ошибке коммуникации не продолжайте многократные попытки вслепую.', 150, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему Tesla не начинает DC-зарядку после подключения переходника?')
UNION ALL
SELECT 'charging', 'Можно ли использовать Tesla Supercharger за пределами Кыргызстана?', 'Доступность зависит от региона автомобиля, конкретной станции и её правил доступа, оплаты и совместимости. Перед поездкой проверяйте доступность именно для своего автомобиля в приложении и навигации Tesla.', 160, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли использовать Tesla Supercharger за пределами Кыргызстана?')
UNION ALL
SELECT 'charging', 'Почему под машиной появляется пар во время зимней зарядки?', 'Работа климатической системы и терморегуляции батареи может создавать конденсат и видимый пар на холоде. Но густой дым, запах горелой изоляции, необычный звук или ошибки — не норма: прекратите зарядку и отойдите, при опасности вызывайте экстренные службы.', 170, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему под машиной появляется пар во время зимней зарядки?')
UNION ALL
SELECT 'adapters', 'Почему один CCS2-переходник работает на одной Tesla и не работает на другой?', 'У разных моделей, годов и регионов отличаются поддерживаемые протоколы и аппаратная конфигурация. На некоторых автомобилях для CCS требуется ретрофит. Сверьте совместимость по конкретной машине, а не по внешней форме разъёма.', 90, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему один CCS2-переходник работает на одной Tesla и не работает на другой?')
UNION ALL
SELECT 'adapters', 'Безопасно ли брать переходник GB/T–Tesla в аренду?', 'Аренда не гарантирует совместимости и исправности. Проверьте назначение AC или DC, ток и напряжение, целостность корпуса и контактов, подходящую модель автомобиля и станции. При сомнениях не подключайте устройство.', 100, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Безопасно ли брать переходник GB/T–Tesla в аренду?')
UNION ALL
SELECT 'adapters', 'Что делать, если переходник нагревается или пахнет гарью?', 'Немедленно штатно остановите зарядку; не трогайте горячие или повреждённые контакты, не пытайтесь отсоединять их силой. Сообщите оператору и обратитесь к специалисту. При дыме или возгорании отойдите и вызовите экстренные службы.', 110, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать, если переходник нагревается или пахнет гарью?')
UNION ALL
SELECT 'adapters', 'Можно ли через простой механический переходник преобразовать GB/T в CCS2 или NACS?', 'Не всегда. Разные стандарты используют разные протоколы и схемы управления. Некоторые комбинации требуют электронного согласования либо аппаратной поддержки в машине. Покупайте только решение с подтверждённой совместимостью.', 120, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли через простой механический переходник преобразовать GB/T в CCS2 или NACS?')
UNION ALL
SELECT 'adapters', 'Почему после подключения адаптера зарядка пишет ошибку коммуникации?', 'Возможны неподдерживаемый протокол, проблема электроники адаптера, неполная фиксация или ошибка станции. Зафиксируйте точный текст ошибки, проверьте документацию устройства и обратитесь к оператору; при повторных сбоях нужна диагностика.', 130, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему после подключения адаптера зарядка пишет ошибку коммуникации?')
UNION ALL
SELECT 'battery', 'Что означает снежинка у значка батареи Tesla?', 'Обычно значок говорит об ограниченной из-за холода доступной энергии или мощности. После прогрева ограничения могут уменьшиться. При планировании зимнего маршрута закладывайте дополнительный запас.', 100, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что означает снежинка у значка батареи Tesla?')
UNION ALL
SELECT 'battery', 'Почему зимой запас хода уменьшается даже при спокойной езде?', 'В холодную погоду энергия уходит на отопление, прогрев аккумулятора и преодоление повышенного сопротивления дороги. Также влияют скорость, ветер и шины. Сравнивайте расход при похожих условиях и увеличивайте резерв на трассе.', 110, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему зимой запас хода уменьшается даже при спокойной езде?')
UNION ALL
SELECT 'battery', 'Почему рекуперативное торможение слабее зимой?', 'Холодная или почти полностью заряженная батарея может временно принимать меньше энергии при торможении. Смотрите ограничения на экране и учитывайте изменение замедления при отпускании педали. При предупреждениях тормозной системы нужна диагностика.', 120, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему рекуперативное торможение слабее зимой?')
UNION ALL
SELECT 'battery', 'Нужно ли прогревать Tesla перед выездом зимой?', 'Предварительная подготовка салона и батареи повышает комфорт и может улучшать эффективность. По возможности включайте климат, когда машина подключена к зарядке. Прогрев не заменяет осторожную езду и соответствующие шины.', 130, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Нужно ли прогревать Tesla перед выездом зимой?')
UNION ALL
SELECT 'battery', 'До какого процента лучше заряжать Tesla каждый день?', 'Рекомендации зависят от химии батареи и комплектации. Ориентируйтесь на лимит и подсказки в меню Charging вашего автомобиля: для некоторых LFP-батарей производитель рекомендует периодическую зарядку до 100%, для других ежедневный лимит ниже.', 140, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'До какого процента лучше заряжать Tesla каждый день?')
UNION ALL
SELECT 'battery', 'Что делать после сильного удара днищем в районе батареи?', 'Не продолжайте поездку, если есть утечка, запах, дым, деформация или предупреждения высоковольтной системы. Отойдите и вызовите помощь при опасных признаках. Даже без них после сильного удара желательно провести осмотр батарейного блока и защиты в квалифицированном сервисе.', 150, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать после сильного удара днищем в районе батареи?')
UNION ALL
SELECT 'battery', 'Стоит ли судить о деградации батареи по пробегу на 100%?', 'Нет. Показанный пробег зависит от оценок BMS и условий измерения. Для вывода о состоянии батареи нужны диагностические данные, корректная методика и динамика показателей, а не одно число на экране.', 160, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Стоит ли судить о деградации батареи по пробегу на 100%?')
UNION ALL
SELECT 'service', 'Почему Tesla издаёт скрип или стук при повороте руля?', 'Возможны износ элементов подвески и рулевого управления, опор, шарниров или креплений. Необходимо определить место и условия возникновения звука; при люфте руля, ухудшении управляемости или сильном стуке отложите поездку до осмотра.', 40, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему Tesla издаёт скрип или стук при повороте руля?')
UNION ALL
SELECT 'service', 'Почему при торможении слышен скрежет, хотя колодки редко используются?', 'На электромобилях из-за рекуперации механические тормоза могут использоваться реже, а диски — покрываться коррозией. Но скрежет может указывать и на износ колодок, застрявший камень или повреждение. При постоянном звуке нужна проверка тормозов.', 50, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему при торможении слышен скрежет, хотя колодки редко используются?')
UNION ALL
SELECT 'service', 'Что делать, если перестала работать камера заднего вида или боковая камера?', 'Проверьте загрязнение и внешние повреждения, наличие системного уведомления и работоспособность после штатного перезапуска интерфейса. Не полагайтесь на ассистенты парковки при неисправной камере; стойкую ошибку проверяйте в сервисе.', 60, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать, если перестала работать камера заднего вида или боковая камера?')
UNION ALL
SELECT 'service', 'Почему в Tesla плохо греет печка или появился шум климатической системы?', 'Причины могут включать особенности работы теплового насоса, загрязнение фильтров, неисправность датчиков, вентилятора или контура отопления. Сначала проверьте настройки и ошибки. Ремонт холодильного и высоковольтного оборудования доверяйте специалистам.', 70, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему в Tesla плохо греет печка или появился шум климатической системы?')
UNION ALL
SELECT 'service', 'Можно ли самостоятельно заменить 12-вольтовый аккумулятор Tesla?', 'Конструкция низковольтной системы зависит от модели и года: на некоторых автомобилях установлена не свинцовая 12V, а литиевая низковольтная батарея другого номинала. Перед заменой сверяйте спецификацию и процедуру производителя; при отсутствии опыта обращайтесь в сервис.', 80, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли самостоятельно заменить 12-вольтовый аккумулятор Tesla?')
UNION ALL
SELECT 'service', 'Что означает предупреждение о низковольтной батарее?', 'Оно может указывать на проблему вспомогательного питания, аккумулятора или системы его зарядки. Не игнорируйте уведомление: автомобиль может перестать нормально включаться. Зафиксируйте точный текст и обратитесь за диагностикой.', 90, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что означает предупреждение о низковольтной батарее?')
UNION ALL
SELECT 'service', 'Почему появляется вибрация на скорости после замены шин?', 'Частые причины — дисбаланс, деформация диска, неровная посадка шины или проблемы подвески. Проверьте давление, соответствие размеров и балансировку; при сильной вибрации избегайте высокой скорости до осмотра.', 100, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему появляется вибрация на скорости после замены шин?')
UNION ALL
SELECT 'service', 'Почему Tesla щёлкает при начале движения или зарядке?', 'Отдельные щелчки высоковольтных контакторов могут быть штатными. Но частое повторение с ошибками, потерей тяги или отказом зарядки требует диагностики. Не вскрывайте высоковольтные узлы самостоятельно.', 110, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему Tesla щёлкает при начале движения или зарядке?')
UNION ALL
SELECT 'software', 'Что делать, если пропал интернет в Tesla?', 'Уточните, не исчезла ли только мобильная связь, работает ли Wi-Fi и нет ли временного сбоя оператора. Перезапуск экрана не решает все проблемы модема. При стойком отсутствии связи после обновления запишите версию ПО и ошибки для диагностики.', 50, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать, если пропал интернет в Tesla?')
UNION ALL
SELECT 'software', 'Можно ли установить местную SIM-карту в американскую Tesla?', 'Поддержка и способ подключения зависят от поколения модема, региона и конфигурации автомобиля. Замена SIM не гарантирует доступ к сервисам Tesla и может потребовать специализированной настройки. Не доверяйте обещаниям универсального решения без проверки модели.', 60, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли установить местную SIM-карту в американскую Tesla?')
UNION ALL
SELECT 'software', 'Почему телефон перестал открывать Tesla как ключ?', 'Проверьте заряд телефона, Bluetooth, разрешения и фоновую работу приложения Tesla. Убедитесь, что телефон остаётся в списке ключей автомобиля. Держите запасную ключ-карту; при необходимости выполните повторную привязку по инструкции.', 70, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему телефон перестал открывать Tesla как ключ?')
UNION ALL
SELECT 'software', 'Что делать, если потеряна единственная ключ-карта Tesla?', 'Не удаляйте работающий телефон-ключ из настроек. Для добавления ключей могут потребоваться существующий авторизованный ключ и подтверждение владения. Свяжитесь с официальной поддержкой или компетентным сервисом; не используйте сомнительные методы обхода защиты.', 80, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать, если потеряна единственная ключ-карта Tesla?')
UNION ALL
SELECT 'software', 'Почему после обновления Tesla изменились функции или интерфейс?', 'Обновления могут переносить элементы меню, менять поведение помощников и доступность региональных функций. Проверьте примечания к версии и настройки. Если пропала критическая функция или появились ошибки, зафиксируйте версию ПО и обратитесь за диагностикой.', 90, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему после обновления Tesla изменились функции или интерфейс?')
UNION ALL
SELECT 'software', 'Почему карта автомобиля не показывает зарядные станции в Кыргызстане?', 'Доступность точек в штатной навигации зависит от картографической базы, региона, совместимости и интеграции операторов. Для локальных станций используйте дополнительно tesla.bosh.kg и проверяйте разъёмы, статус и варианты оплаты.', 100, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему карта автомобиля не показывает зарядные станции в Кыргызстане?')
UNION ALL
SELECT 'software', 'Стоит ли устанавливать неофициальные сертификаты и прошивки Tesla?', 'Неизвестные изменения программной конфигурации могут нарушить работу подключённых функций, диагностики и систем безопасности. Перед вмешательством уточните конкретную проблему и последствия для вашей модели, резервируйте доступные данные и обращайтесь к компетентному специалисту.', 110, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Стоит ли устанавливать неофициальные сертификаты и прошивки Tesla?')
UNION ALL
SELECT 'home', 'Можно ли заряжать Tesla через обычный удлинитель?', 'Обычные бытовые удлинители часто не рассчитаны на длительную высокую нагрузку и могут перегреваться. Предпочтительна проверенная выделенная линия с подходящей защитой и зарядным оборудованием. Не используйте повреждённые розетки, переходники и самодельные соединения.', 30, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли заряжать Tesla через обычный удлинитель?')
UNION ALL
SELECT 'home', 'Почему домашняя зарядка идёт медленнее ожидаемого?', 'Скорость ограничивается доступной мощностью сети, настройкой тока, зарядным устройством автомобиля и кабелем. Проверьте установленный ток, нагрев контактов и падение напряжения. Проблемы электропроводки должен устранять электрик.', 40, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему домашняя зарядка идёт медленнее ожидаемого?')
UNION ALL
SELECT 'home', 'Что делать, если в доме выбивает автомат во время зарядки?', 'Остановите зарядку, не увеличивайте номинал автомата без расчётов. Причиной может быть перегрузка линии, неисправность защиты, утечка тока или плохой контакт. Попросите квалифицированного электрика проверить схему и зарядное оборудование.', 50, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Что делать, если в доме выбивает автомат во время зарядки?')
UNION ALL
SELECT 'buying', 'На что смотреть при покупке Tesla после американского аукциона?', 'Проверьте VIN, историю повреждений и ремонта, состояние батареи и силовой структуры, зарядного порта, подушек безопасности, электроники и документов. Машину после затопления или серьёзного удара необходимо обследовать особенно тщательно.', 40, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'На что смотреть при покупке Tesla после американского аукциона?')
UNION ALL
SELECT 'buying', 'Как проверить, есть ли на Tesla поддержка CCS-зарядки?', 'Возможность зависит от конкретной модели, года, рынка и аппаратной конфигурации. Проверьте сведения автомобиля и совместимость по VIN или через профильную диагностику. Не покупайте адаптер, пока не подтверждена поддержка нужного протокола.', 50, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Как проверить, есть ли на Tesla поддержка CCS-зарядки?')
UNION ALL
SELECT 'buying', 'Почему дешёвая Tesla может оказаться дорогой в обслуживании?', 'Начальная цена не отражает скрытых последствий ДТП, деградации или повреждений батареи, отсутствующих модулей и программных ограничений. Перед покупкой заложите стоимость полной диагностики и потенциальных работ.', 60, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему дешёвая Tesla может оказаться дорогой в обслуживании?')
UNION ALL
SELECT 'other', 'Как выбирать зимние шины для тяжёлого электромобиля?', 'Проверяйте допущенные размеры, индекс нагрузки и скорости, качество зимнего сцепления и параметры диска. Важны не только шум и запас хода, но и безопасность торможения на снегу и льду.', 20, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Как выбирать зимние шины для тяжёлого электромобиля?')
UNION ALL
SELECT 'other', 'Почему у Tesla быстро изнашивается внутренняя сторона шин?', 'Возможны нарушение углов установки колёс, особенности подвески, давление или стиль езды. Проверьте геометрию, состояние сайлентблоков и давление. Износ нельзя списывать только на массу электромобиля.', 30, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Почему у Tesla быстро изнашивается внутренняя сторона шин?')
UNION ALL
SELECT 'other', 'Можно ли оставить Tesla на несколько недель без поездок?', 'Перед длительной стоянкой ориентируйтесь на рекомендации автомобиля по уровню заряда; при возможности оставьте его подключённым к исправному зарядному оборудованию с установленным лимитом. Учитывайте потребление охранных и фоновых функций и не храните машину с почти пустой батареей.', 40, 1 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM ev_faq WHERE question = 'Можно ли оставить Tesla на несколько недель без поездок?');
